fn DL_DL_000(x: f64, z: f64, NF: f64) -> f64 {
    let res: f64 = 39. / 8. * (1.0 / NQCD) + (- 39. / 8. * NQCD) + 3. / 4. * CF + (- 1. / 6. * (pi * pi) * (1.0 / NQCD)) + 1. / 6. * (pi * pi) * NQCD;
    return res;
}

fn DL_DL_100(x: f64, z: f64, NF: f64) -> f64 {
    let res: f64 = 3.0 * lmur * (1.0 / NQCD) + (- 3.0 * lmur * NQCD);
    return res;
}

